<?php require 'config/bootstrap.php';auth();$s=$pdo->prepare('SELECT * FROM produk WHERE user_id=? ORDER BY created_at DESC');$s->execute([me()['id']]);$rows=$s->fetchAll();headpage('Produk saya');?><div class="d-flex justify-content-between"><h1>Produk Saya</h1><a class="btn btn-green" href="product-form.php">Tambah</a></div><div class="row g-3"><?php foreach($rows as $p):?><div class="col-md-4"><div class="card"><?php if($p['gambar_produk']):?><img src="<?=e($p['gambar_produk'])?>" alt=""><?php endif;?><div class="card-body"><h5><?=e($p['nama_produk'])?></h5><p><?=e($p['status_produk'])?></p><a class="btn btn-sm btn-outline-success" href="product-form.php?id=<?=(int)$p['id']?>">Edit</a><form class="d-inline" method="post" action="actions/product-delete.php"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="btn btn-sm btn-outline-danger" onclick="return confirm('Hapus produk?')">Hapus</button></form></div></div></div><?php endforeach;?><?php if(!$rows):?><p>Belum ada produk. Klik Tambah untuk mulai.</p><?php endif;?></div><?php footpage();